using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
namespace DragonCompanion {
// Deform one intact drawing; never splice different bodies together.
public static class ActivityRig {
 static float Ease(float t){t=Math.Max(0,Math.Min(1,t));return t*t*(3-2*t);}
 static float Area(float x,float y,float cx,float cy,float rx,float ry){float dx=(x-cx)/rx,dy=(y-cy)/ry,r=dx*dx+dy*dy;if(r>=1)return 0;float w=1-r;return w*w*w;}
 static float FlatArea(float x,float y,float cx,float cy,float rx,float ry){float dx=(x-cx)/rx,dy=(y-cy)/ry;return 1-Ease(((float)Math.Sqrt(dx*dx+dy*dy)-.45f)/.55f);}
 public static float SipAmount(float phase){return Ease((phase-.08f)/.25f)*(1-Ease((phase-.62f)/.28f));}
 public static PointF Displacement(string key,string style,float x,float y,float phase){bool pixel=style=="pixel";double angle=phase*Math.PI*2;float dx=0,dy=0;
  if(key=="waiting"){float gesture=(float)Math.Sin(Math.PI*Ease(phase/.35f));if(phase>=.35f)gesture=0;dx=.8f*gesture*Area(x,y,pixel?109:112,pixel?105:112,10,13);}
  return new PointF(dx,dy);
 }
 static byte[] Read(Bitmap image){var bits=image.LockBits(new Rectangle(Point.Empty,image.Size),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var data=new byte[image.Width*image.Height*4];for(int y=0;y<image.Height;y++)Marshal.Copy(IntPtr.Add(bits.Scan0,y*bits.Stride),data,y*image.Width*4,image.Width*4);return data;}finally{image.UnlockBits(bits);}}
 static Bitmap Write(byte[] bytes,int width,int height){var image=new Bitmap(width,height,PixelFormat.Format32bppArgb);var bits=image.LockBits(new Rectangle(0,0,width,height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{for(int y=0;y<height;y++)Marshal.Copy(bytes,y*width*4,IntPtr.Add(bits.Scan0,y*bits.Stride),width*4);}finally{image.UnlockBits(bits);}return image;}
 static Bitmap Warp(Bitmap plate,byte[] source,string key,string style,float phase){int width=plate.Width,height=plate.Height;float scale=Math.Min(176f/width,176f/height),left=(192-width*scale)/2,top=184-height*scale;var output=(byte[])source.Clone();
  for(int y=0;y<height;y++)for(int x=0;x<width;x++){float cx=x*scale+left,cy=y*scale+top;var motion=Displacement(key,style,cx,cy,phase);if(Math.Abs(motion.X)+Math.Abs(motion.Y)<.00001)continue;float sx=cx,sy=cy;for(int n=0;n<10;n++){var offset=Displacement(key,style,sx,sy,phase);float ex=sx+offset.X-cx,ey=sy+offset.Y-cy;if(Math.Abs(ex)+Math.Abs(ey)<.0001f)break;var xx=Displacement(key,style,sx+.1f,sy,phase);var yy=Displacement(key,style,sx,sy+.1f,phase);float j00=1+(xx.X-offset.X)*10,j01=(yy.X-offset.X)*10,j10=(xx.Y-offset.Y)*10,j11=1+(yy.Y-offset.Y)*10,det=j00*j11-j01*j10;if(Math.Abs(det)<.08f)break;sx-=(j11*ex-j01*ey)/det;sy-=(-j10*ex+j00*ey)/det;}sx=(sx-left)/scale;sy=(sy-top)/scale;int ix=(int)Math.Floor(sx),iy=(int)Math.Floor(sy);float fx=sx-ix,fy=sy-iy,alpha=0,b=0,g=0,r=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){int px=ix+dx,py=iy+dy;if(px<0||py<0||px>=width||py>=height)continue;int p=(py*width+px)*4;float w=(dx==0?1-fx:fx)*(dy==0?1-fy:fy)*source[p+3];alpha+=w;b+=source[p]*w;g+=source[p+1]*w;r+=source[p+2]*w;}int q=(y*width+x)*4;output[q]=(byte)Math.Round(alpha==0?0:b/alpha);output[q+1]=(byte)Math.Round(alpha==0?0:g/alpha);output[q+2]=(byte)Math.Round(alpha==0?0:r/alpha);output[q+3]=(byte)Math.Round(alpha);}
  return Write(output,width,height);
 }
 static Bitmap Blink(Bitmap plate,string style,float closure){var image=(Bitmap)plate.Clone();if(closure<=0)return image;float scale=Math.Min(176f/image.Width,176f/image.Height),left=(192-image.Width*scale)/2,top=184-image.Height*scale;bool pixel=style=="pixel";float cy=pixel?75:114;using(var graphics=Graphics.FromImage(image)){graphics.SmoothingMode=SmoothingMode.AntiAlias;foreach(float cx in pixel?new float[]{70,100}:new float[]{72,112}){float px=(cx-left)/scale,py=(cy-top)/scale,rx=10.5f/scale,ry=8.5f/scale;var eye=new RectangleF(px-rx,py-ry,2*rx,2*ry);var skin=plate.GetPixel((int)px,Math.Min(plate.Height-1,(int)(py+ry+1)));using(var original=plate.Clone(Rectangle.Intersect(Rectangle.Ceiling(eye),new Rectangle(Point.Empty,plate.Size)),PixelFormat.Format32bppArgb)){var saved=graphics.Save();using(var path=new GraphicsPath()){path.AddEllipse(eye);graphics.SetClip(path,CombineMode.Intersect);}using(var brush=new SolidBrush(skin))graphics.FillEllipse(brush,eye);if(closure<.9f){float height=Math.Max(.7f,eye.Height*(1-closure));graphics.DrawImage(original,new RectangleF(eye.X,py-height/2,eye.Width,height));}graphics.Restore(saved);}if(closure>.35f)using(var pen=new Pen(Color.FromArgb((int)(255*Ease((closure-.35f)/.65f)),78,49,90),1.1f/scale)){pen.StartCap=pen.EndCap=LineCap.Round;graphics.DrawBezier(pen,px-rx*.65f,py,px-rx*.3f,py+1.5f/scale,px+rx*.3f,py+1.5f/scale,px+rx*.65f,py);}}}return image;}
 public static Bitmap FitOriginal(Bitmap original,Bitmap reference){var source=ActivityArt.OpaqueBounds(original);var target=ActivityArt.OpaqueBounds(reference);float anchor=ReadingBook.HeadCenter(reference),sourceAnchor=ReadingBook.HeadCenter(original),scale=target.Height/(float)source.Height;scale=Math.Min(scale,(anchor-4)/Math.Max(1,sourceAnchor-source.Left));scale=Math.Min(scale,(reference.Width-4-anchor)/Math.Max(1,source.Right-sourceAnchor));var result=new Bitmap(reference.Width,reference.Height,PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(result)){graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;graphics.DrawImage(original,new RectangleF(anchor-sourceAnchor*scale,target.Bottom-source.Bottom*scale,original.Width*scale,original.Height*scale));}return result;}
 public static Bitmap[] Create(Bitmap reference,string key,string style,int count){using(var plate=key=="complete"?FitOriginal(Art.OriginalCelebration(style),reference):(Bitmap)reference.Clone()){
   if(key=="complete"){var pose=(Bitmap)plate.Clone();var still=new Bitmap[count];for(int i=0;i<count;i++)still[i]=pose;return still;}
   var result=new Bitmap[count];var source=Read(plate);var blinks=new Dictionary<int,Bitmap>();for(int i=0;i<count;i++){float phase=i/(float)count;if(key=="rest"){float blink=phase<.69f||phase>.74f?0:(phase<.715f?Ease((phase-.69f)/.025f):1-Ease((phase-.715f)/.025f));int level=(int)Math.Round(blink*4);Bitmap frame;if(!blinks.TryGetValue(level,out frame)){frame=Blink(plate,style,level/4f);blinks.Add(level,frame);}result[i]=frame;}else result[i]=Warp(plate,source,key,style,phase);}return result;
  }}
}
}
